import RNA, random, time, multiprocessing as mp
target = "......((.......((.((.......((.((...............)).........((...............)).)).......)).((.......((...............)).......)).((.......((.((...............)).........((...............)).)).......)).((.......((...............)).......)).((.......((.((...............)).........((...............)).)).......)).((.......((...........((...............)).)).......)).)).......))......"

stack=[]; pairs={}
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j

def dist(s):
    return RNA.bp_distance(RNA.fold_compound(s).mfe()[0], target)

# template init
base=['A']*len(target)
for i,j in pairs.items():
    if i<j:
        base[i]='G'; base[j]='C'

def worker(seed):
    random.seed(seed)
    cur = ''.join(base)
    # jitter init: random WC at pairs
    for i,j in pairs.items():
        if i<j and random.random()<0.5:
            if random.random()<0.5: base[i]='C'; base[j]='G'
            else: base[i]='G'; base[j]='C'
    cur=''.join(base)
    cur_d = dist(cur)
    best, best_d = cur, cur_d
    deadline = time.time() + 150
    while time.time() < deadline and best_d > 0:
        c = list(cur)
        for _ in range(random.choice([1,1,1,2])):
            i = random.randrange(len(c))
            c[i] = random.choice('ACGU')
        c = ''.join(c); d = dist(c)
        if d < cur_d or (d == cur_d and random.random() < 0.4):
            cur, cur_d = c, d
            if d < best_d: best, best_d = c, d
    return best_d, best

if __name__ == '__main__':
    with mp.Pool(16) as p:
        results = p.map(worker, range(16))
    results.sort()
    print("best", results[0][0])
    print(results[0][1])
