import RNA, random, time, multiprocessing as mp
target = "......((.......((.((.......((.((...............)).........((...............)).)).......)).((.......((...............)).......)).((.......((.((...............)).........((...............)).)).......)).((.......((...............)).......)).((.......((.((...............)).........((...............)).)).......)).((.......((...........((...............)).)).......)).)).......))......"

stack=[]; pairs={}
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j

WC = {'A':'U','U':'A','G':'C','C':'G'}
def dist(s):
    return RNA.bp_distance(RNA.fold_compound(s).mfe()[0], target)

# Build a clean structured template: GC at all pairs, A at unpaired, with GC clamps at closing
base=['A']*len(target)
for i,j in pairs.items():
    if i<j:
        base[i]='G'; base[j]='C'

def worker(seedn):
    random.seed(seedn)
    # start from template + small jitter
    seq = base[:]
    for i in range(len(seq)):
        if random.random()<0.15:
            seq[i] = random.choice('ACGU')
    cur = ''.join(seq)
    cur_d = dist(cur)
    best, best_d = cur, cur_d
    deadline = time.time() + 140
    while time.time() < deadline and best_d > 0:
        c = list(cur)
        # structure-aware move: pick a position; if paired, mutate to keep WC; if unpaired, random
        nmut = random.choice([1,1,2])
        for _ in range(nmut):
            i = random.randrange(len(c))
            if i in pairs:
                j = pairs[i]
                # pick a WC pair type
                p = random.choice(['GC','CG','AU','UA','GU','UG'])
                c[i]=p[0]; c[j]=p[1]
            else:
                c[i] = random.choice('ACGU')
        c = ''.join(c); d = dist(c)
        if d < cur_d or (d == cur_d and random.random() < 0.45):
            cur, cur_d = c, d
            if d < best_d: best, best_d = c, d
    return best_d, best

if __name__ == '__main__':
    with mp.Pool(20) as p:
        results = p.map(worker, range(40))
    results.sort()
    print("best", results[0][0])
    print(results[0][1])
    print("2nd", results[1][0])
